// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // Fuzz parameters: from address and an array length selector (as uint) and a value v.
    // We let the fuzzer choose an address 'from' and a uint 'n' to build an array of length n (bounded >=1)
    function testFuzz_property(address from, uint256 n, uint256 v) public {
        // keep n in a reasonable (but wide) range for gas; ensure at least 1 (admissible domain)
        n = bound(n, 1, 10); // _tos.length must be > 0 per contract's require

        // Deploy a recording helper that exposes the exact signature transferFrom(address,address,uint256)
        // and will REVERT if called with an index that decodes to the zero address sentinel we use to detect out-of-bounds.
        RecorderReverter rec = new RecorderReverter();

        // Build _tos array of length n with distinct addresses that match what RecorderReverter expects.
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            // Fill with the recorder's address so the called callee exists and can record.
            tos[i] = address(rec);
        }

        // The general rule we check: the reference implementation always returns true (call sequence succeeds)
        // for any non-empty _tos when the callee accepts and records calls. We detect success via the returned bool.
        // Use try/catch to observe whether c.transfer reverts.
        bool ok;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference C should always complete without revert and return true when the callee records/accepts calls.
        // Therefore ok must be true for all admissible inputs. The mutant with i<=_tos.length can trigger an out-of-bounds
        // extra call that the RecorderReverter is designed to reject, making ok false for some inputs; the fuzzer will find such.
        assertTrue(ok);

        // Also verify the recorder saw exactly n calls (sanity, reads observable behaviour of helper)
        // This is not the single required assertion but helps ensure we observed the intended interaction.
        require(rec.calls() == n, "recorder saw wrong number of calls");
    }
}

// Helper: exposes the exact signature used by C (transferFrom(address,address,uint256)) and records calls.
// It will accept well-formed calls and increment a counter. If it is invoked with a special marker
// (we simulate an out-of-bounds bad call by letting decoding produce address(0) for the 'to' param),
// it reverts, distinguishing the mutant's extra iteration.
contract RecorderReverter {
    uint public callCount;

    // This function matches the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        // If the callee sees an address(0) in `to`, treat it as an invalid/out-of-bounds artefact and revert.
        if (to == address(0)) revert("invalid to");
        callCount += 1;
        return true;
    }

    // Accessor to allow the test to read how many calls were recorded.
    function calls() external view returns (uint) { return callCount; }
}
